//! Independent immutable SYS_APPEARANCE+field-write algorithms, and finite DATA comparison.
//! Generic fixture pages certify no source coverage; actual host tests are separate.
pub use dq_analyze::original_policy_descriptors as allow_registry_fields;
pub use dq_analyze::{lint,incr,tree,pat,pat_match,util,parity};
#[path="../fixtures/original_policies/sys_appearance_field_write.rs"]pub mod field_write_original;
pub mod dm{pub use dq_analyze::dm::{pylines,sys};pub use super::field_write_original as field_write;}
#[path="../fixtures/original_policies/sys_appearance.rs"]mod original;
#[path="../fixtures/native-sys-appearance/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod test_scratch;
use std::{path::Path,sync::Arc};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<dq_analyze::captured_generator_budget::Budget>,pass:std::cell::Cell<usize>}
impl dq_analyze::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,dq_analyze::captured_raw_file::RawPolicyViews<'_>)->Result<bool,dq_analyze::captured_reactive_reads::Failure>)->Result<bool,dq_analyze::captured_reactive_reads::Failure>{let pass=self.pass.get();self.pass.set(pass+1);for(relative,text)in &self.rows{if pass==0&&!dq_analyze::captured_raw_file::is_code_dm(relative){continue}if !dq_analyze::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
struct Text<'a>(&'a dq_analyze::captured_sys_appearance_pages::AppearanceData);impl dq_analyze::baseline::SiteText for Text<'_>{fn site_text(&self,relative:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(site,_)|site.rel==relative&&site.line as usize==line).map(|(_,text)|text.clone()).expect("actual delivered original SYS_APPEARANCE line absent")}}
fn record(outcome:&dq_analyze::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn failure(error:dq_analyze::captured_reactive_reads::Failure)->Box<dyn std::error::Error>{match error{dq_analyze::captured_reactive_reads::Failure::Operational(actual)=>Box::new(actual),dq_analyze::captured_reactive_reads::Failure::Unsupported(message)=>message.into()}}
fn main()->Result<(),Box<dyn std::error::Error>>{use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/sys_appearance.rs"))),"2284cb74ab098799ad284eae6a53811bb28dfa7f");assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/sys_appearance_field_write.rs"))),"83363cdd6d070111676dda2c9e9ea504b8cee5fa");
 for case in fixture::CASES{let files=fixture::files(case).ok_or("SYS_APPEARANCE fixture absent")?;let root=test_scratch::dir(&format!("whole-sys-appearance-{case}"));for(relative,bytes)in &files{let target=root.join(relative);std::fs::create_dir_all(target.parent().ok_or("SYS_APPEARANCE fixture parent")?)?;std::fs::write(target,bytes)?;}
 let options=dq_analyze::run::Options{root:root.clone(),lints:vec!["sys/appearance".into()],raw:true,no_cache:true,..Default::default()};let mut registry=lint::Registry::default();original::register(&mut registry);let old=dq_analyze::run::Engine::new(registry,options.clone())?;let expected=old.run_one(old.reg.lints[0].as_ref());assert!(expected.internal_error.is_none());assert!(!expected.run.sites.is_empty(),"real source must trigger SYS_APPEARANCE fixture {case}");let mut registry=lint::Registry::default();dq_analyze::lints::sys_appearance::register(&mut registry);let shared=dq_analyze::run::Engine::new(registry,options)?;let delegated=shared.run_one(shared.reg.lints[0].as_ref());assert_eq!(record(&delegated),record(&expected),"entire frozen SYS_APPEARANCE+field-write/shared legacy policy {case}");
 let budget=dq_analyze::captured_generator_budget::Budget::new(32*1024*1024)?;let mut rows=Vec::new();for(relative,bytes)in &files{if !relative.ends_with(".dm")||!(relative.starts_with("code/")||relative.starts_with("maps/")){continue}let source=dm_preprocess::AcquiredSource::from_original_bytes(bytes.clone(),());rows.push(((*relative).to_owned(),source.lease().source_text().clone()));}rows.reverse();let pages=Pages{root:&root,rows,budget:Arc::clone(&budget),pass:std::cell::Cell::new(0)};let bytes=files.iter().find(|(p,_)|*p=="tools/ci/lint_scopes.toml").ok_or("SYS_APPEARANCE initial config absent")?.1.as_slice();let config=dq_analyze::captured_raw_file::Config::capture(dq_analyze::captured_raw_policy::Configuration::Captured(bytes))?;let data=dq_analyze::captured_sys_appearance_pages::collect(&pages,&config,&budget,&||Ok(())).map_err(failure)?;assert_eq!(data.sites(),expected.run.sites.as_slice(),"whole sites {case}");assert_eq!(data.allow_used(),expected.allow_used.as_slice(),"ordered ALLOW {case}");for(site,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize));}
 let empty=Default::default();let scope=config.borrowed_report_scope("sys/appearance","sys").unwrap_or(&empty);let actual=dq_analyze::policy_finish::finish_report(dq_analyze::captured_sys_appearance_pages::metadata(),scope,&Text(&data),dq_analyze::lint::Run{sites:data.sites().to_vec(),notes:Vec::new()},data.allow_used().to_vec(),Default::default(),&root,&None,true,|_,_,_|panic!("SYS_APPEARANCE has no custom finish"),|_,_|false);assert_eq!(record(&actual),record(&expected),"entire immutable old/native SYS_APPEARANCE report {case}");println!("SYS_APPEARANCE_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"case":case,"record":record(&actual)}));
 }Ok(())}
